// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // deployer (this test contract) is the initial owner
        vm.prank(address(this));
        bool ok = c.setOwner(newOwner);
        assertTrue(ok && c.owner() == newOwner);
    }
}
